import urllib.request, json, urllib.parse
for repo in ['scanpy']:
    page=1
    while True:
      url=f'https://quay.io/api/v1/repository/biocontainers/{repo}/tag/?limit=100&page={page}&onlyActiveTags=true'
      data=json.load(urllib.request.urlopen(url))
      tags=data.get('tags',[])
      print('page',page,'n',len(tags))
      for t in tags:
          name=t['name']
          if name.startswith('1.9') or name.startswith('1.10') or name.startswith('1.11') or name.startswith('1.12'):
              print(name, t.get('last_modified'), t.get('manifest_digest','')[:16])
      if data.get('has_additional'):
          page+=1
      else:
          break
